// Generated by AI (UnitTest MCP)
use rusqlite::{params, Connection, OptionalExtension, Row};

use crate::decay::ACTIVE_THRESHOLD;
use crate::embed::{self, Embedder};
use crate::error::{LodestarError, Result};
use crate::model::Knowledge;
use crate::util::short_hash;

use super::{collect, LodestarStore};

const KNOWLEDGE_COLS: &str =
    "id, statement, evidence, weight, half_life_hours, confirmed_at, created_at, \
     retired_at, retired_by, retired_reason, superseded_by";

/// How many lessons one read may warm the index with. Bounded so the first
/// search after an upgrade is slower once, not unusable.
const MAX_BACKFILL_PER_READ: usize = 64;

impl LodestarStore {
    /// Insert or reconfirm a knowledge node. Re-recording the same statement
    /// bumps its weight and resets its revalidation clock.
    pub fn record_knowledge(
        &self,
        statement: &str,
        evidence: &str,
        half_life_hours: f64,
        now: i64,
    ) -> Result<Knowledge> {
        let id = upsert_knowledge(&self.conn, statement, evidence, half_life_hours, now)?;
        self.index_statement(&id, statement, now);
        self.get_knowledge(&id)?
            .ok_or_else(|| LodestarError::Invalid("knowledge vanished after insert".into()))
    }

    /// Record knowledge from one stable logical source.
    ///
    /// The source mapping is the identity an editable memory note needs: the
    /// statement hash identifies one version, while `source_ref` identifies the
    /// note across versions. Repeating the same text reconfirms one row. Changed
    /// text moves the source and retires the previous row once no other source
    /// still names it.
    pub fn record_sourced_knowledge(
        &self,
        statement: &str,
        evidence: &str,
        half_life_hours: f64,
        source_ref: &str,
        actor: &str,
        now: i64,
    ) -> Result<(Knowledge, Option<String>)> {
        let transaction = self.conn.unchecked_transaction()?;
        let previous: Option<String> = transaction
            .query_row(
                "SELECT knowledge_id FROM knowledge_sources WHERE source_ref = ?1",
                params![source_ref],
                |row| row.get(0),
            )
            .optional()?;
        let id = upsert_knowledge(&transaction, statement, evidence, half_life_hours, now)?;
        let replaced = previous.filter(|previous| previous != &id);
        let mut superseded = None;

        transaction.execute(
            "INSERT INTO knowledge_sources (source_ref, knowledge_id, updated_at)
             VALUES (?1, ?2, ?3)
             ON CONFLICT(source_ref) DO UPDATE SET
                 knowledge_id = excluded.knowledge_id,
                 updated_at = excluded.updated_at",
            params![source_ref, id, now],
        )?;

        if let Some(previous) = replaced.as_deref() {
            let remaining: i64 = transaction.query_row(
                "SELECT COUNT(*) FROM knowledge_sources WHERE knowledge_id = ?1",
                params![previous],
                |row| row.get(0),
            )?;
            if remaining == 0 {
                let retired = transaction.execute(
                    "UPDATE knowledge
                     SET retired_at = ?2, retired_by = ?3,
                         retired_reason = ?4, superseded_by = ?5
                     WHERE id = ?1 AND retired_at IS NULL",
                    params![
                        previous,
                        now,
                        actor,
                        format!("source {source_ref} was updated"),
                        id
                    ],
                )?;
                if retired == 1 {
                    superseded = Some(previous.to_string());
                }
            }
        }
        transaction.commit()?;

        self.index_statement(&id, statement, now);
        let knowledge = self
            .get_knowledge(&id)?
            .ok_or_else(|| LodestarError::Invalid("knowledge vanished after insert".into()))?;
        Ok((knowledge, superseded))
    }

    /// The active lesson currently represented by one logical source.
    pub fn active_knowledge_for_source(&self, source_ref: &str) -> Result<Option<Knowledge>> {
        let sql = format!(
            "SELECT {KNOWLEDGE_COLS}
               FROM knowledge
               JOIN knowledge_sources ON knowledge_sources.knowledge_id = knowledge.id
              WHERE knowledge_sources.source_ref = ?1
                AND knowledge.retired_at IS NULL"
        );
        self.conn
            .query_row(&sql, params![source_ref], row_to_knowledge)
            .optional()
            .map_err(Into::into)
    }

    /// Detach one logical source and retire its lesson only when no source
    /// still carries it.
    pub fn retire_knowledge_source(
        &self,
        source_ref: &str,
        actor: &str,
        reason: &str,
        now: i64,
    ) -> Result<(Knowledge, bool)> {
        let transaction = self.conn.unchecked_transaction()?;
        let id: String = transaction
            .query_row(
                "SELECT knowledge_id FROM knowledge_sources WHERE source_ref = ?1",
                params![source_ref],
                |row| row.get(0),
            )
            .optional()?
            .ok_or_else(|| LodestarError::NotFound(source_ref.to_string()))?;
        transaction.execute(
            "DELETE FROM knowledge_sources WHERE source_ref = ?1",
            params![source_ref],
        )?;
        let remaining: i64 = transaction.query_row(
            "SELECT COUNT(*) FROM knowledge_sources WHERE knowledge_id = ?1",
            params![id],
            |row| row.get(0),
        )?;
        let retired = remaining == 0
            && transaction.execute(
                "UPDATE knowledge
                 SET retired_at = ?2, retired_by = ?3, retired_reason = ?4
                 WHERE id = ?1 AND retired_at IS NULL",
                params![id, now, actor, reason],
            )? == 1;
        transaction.commit()?;

        let knowledge = self
            .get_knowledge(&id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))?;
        Ok((knowledge, retired))
    }

    /// Embed a statement for semantic recall, best-effort (ADR-0080).
    ///
    /// Deliberately returns nothing and swallows every failure: the index is an
    /// optimisation on *reading* knowledge, and losing a durable lesson because
    /// an optional local model was not running would be a far worse trade than
    /// searching that lesson by substring.
    fn index_statement(&self, id: &str, statement: &str, now: i64) {
        let embedder = Embedder::default();
        match embed::needs_vector(&self.conn, id, &embedder.model) {
            Ok(true) => {}
            _ => return,
        }
        if let Ok(vector) = embedder.embed(statement) {
            let _ = embed::store_vector(&self.conn, id, &embedder.model, &vector, now);
        }
    }

    pub fn get_knowledge(&self, id: &str) -> Result<Option<Knowledge>> {
        let sql = format!("SELECT {KNOWLEDGE_COLS} FROM knowledge WHERE id = ?1");
        let mut stmt = self.conn.prepare(&sql)?;
        let mut rows = stmt.query(params![id])?;
        match rows.next()? {
            Some(row) => Ok(Some(row_to_knowledge(row)?)),
            None => Ok(None),
        }
    }

    /// Re-confirm a knowledge node with fresh evidence (resets the decay clock).
    pub fn reconfirm_knowledge(&self, id: &str, now: i64) -> Result<bool> {
        let changed = self.conn.execute(
            "UPDATE knowledge SET confirmed_at = ?2, weight = MIN(1.0, weight + 0.1) WHERE id = ?1",
            params![id, now],
        )?;
        Ok(changed == 1)
    }

    /// Knowledge still above the active threshold, strongest first.
    ///
    /// Retired lessons are excluded here rather than at each reader, because
    /// this is the one query the conformance advisory and every other consumer
    /// go through. A rule with several implementations is a rule with several
    /// chances to go stale — which is exactly how `surfaces` was falsified in
    /// three places at once.
    pub fn active_knowledge(&self, now: i64) -> Result<Vec<Knowledge>> {
        let sql = format!(
            "SELECT {KNOWLEDGE_COLS} FROM knowledge
              WHERE retired_at IS NULL
                AND effective_weight(weight, half_life_hours, confirmed_at, ?1) >= ?2
              ORDER BY effective_weight(weight, half_life_hours, confirmed_at, ?1) DESC"
        );
        let mut stmt = self.conn.prepare(&sql)?;
        let rows = stmt.query_map(params![now, ACTIVE_THRESHOLD], row_to_knowledge)?;
        collect(rows)
    }

    /// Reorder `active` by how close each statement is to `query_vector`.
    ///
    /// Returns the reordered list and how many of it were actually ranked.
    /// Unindexed lessons keep their incoming weight order at the end rather
    /// than being dropped — losing a lesson because it has no vector would be
    /// the same silent failure in a different place — but they are *counted*,
    /// because a list that is half meaning and half weight looks exactly like
    /// one that is all meaning.
    pub fn rank_knowledge(
        &self,
        active: Vec<Knowledge>,
        query_vector: &[f32],
        model: &str,
    ) -> Result<(Vec<Knowledge>, usize)> {
        let vectors = embed::vectors_for_model(&self.conn, model)?;
        let mut ranked: Vec<(f32, Knowledge)> = Vec::new();
        let mut unranked: Vec<Knowledge> = Vec::new();
        for k in active {
            match vectors.iter().find(|(id, _)| id == &k.id) {
                Some((_, v)) => ranked.push((embed::cosine(query_vector, v), k)),
                None => unranked.push(k),
            }
        }
        ranked.sort_by(|a, b| b.0.total_cmp(&a.0));
        let count = ranked.len();
        let mut out: Vec<Knowledge> = ranked.into_iter().map(|(_, k)| k).collect();
        out.extend(unranked);
        Ok((out, count))
    }

    /// Give unembedded active knowledge a vector, best-effort, in one request.
    ///
    /// Returns how many were added. Bounded per call so warming a large corpus
    /// costs a bounded amount of a single read rather than one long stall, and
    /// swallows every failure: an unreachable model must cost ranking only.
    pub fn backfill_embeddings(
        &self,
        active: &[Knowledge],
        embedder: &Embedder,
        now: i64,
    ) -> usize {
        let ids: Vec<String> = active.iter().map(|k| k.id.clone()).collect();
        let Ok(missing) = embed::missing_vectors(&self.conn, &embedder.model, &ids) else {
            return 0;
        };
        let batch: Vec<&Knowledge> = active
            .iter()
            .filter(|k| missing.contains(&k.id))
            .take(MAX_BACKFILL_PER_READ)
            .collect();
        if batch.is_empty() {
            return 0;
        }
        let statements: Vec<String> = batch.iter().map(|k| k.statement.clone()).collect();
        let Ok(vectors) = embedder.embed_batch(&statements) else {
            return 0;
        };
        let mut stored = 0;
        for (k, vector) in batch.iter().zip(vectors) {
            if embed::store_vector(&self.conn, &k.id, &embedder.model, &vector, now).is_ok() {
                stored += 1;
            }
        }
        stored
    }

    /// The honest fallback: keep only what literally mentions the query.
    pub fn substring_knowledge(active: Vec<Knowledge>, query: &str) -> Vec<Knowledge> {
        let needle = query.to_lowercase();
        active
            .into_iter()
            .filter(|k| {
                k.statement.to_lowercase().contains(&needle)
                    || k.evidence.to_lowercase().contains(&needle)
            })
            .collect()
    }

    /// Retire one lesson, attributed to whoever ended it (ADR-0019 shape).
    ///
    /// Knowledge was durable-but-decaying with no way to say "this is wrong" or
    /// "this was replaced": a superseded record kept being counted and kept
    /// competing for the capped goal-advisory slots until its half-life ran
    /// out, so the silent-knowledge audit could never reach zero by doing the
    /// work. Retiring says so explicitly.
    ///
    /// Guarded on `retired_at IS NULL` in a single statement so two concurrent
    /// retirements cannot both claim to be the one that did it, and the
    /// original actor and reason are never overwritten.
    pub fn retire_knowledge(
        &self,
        id: &str,
        human: &str,
        reason: &str,
        superseded_by: Option<&str>,
        now: i64,
    ) -> Result<Knowledge> {
        if self.get_knowledge(id)?.is_none() {
            return Err(LodestarError::NotFound(id.to_string()));
        }
        // A dangling replacement would leave a reader with a withdrawn lesson
        // and nowhere to go, so the successor must already exist.
        if let Some(successor) = superseded_by {
            if successor == id {
                return Err(LodestarError::Invalid(format!(
                    "knowledge cannot supersede itself: {id}"
                )));
            }
            if self.get_knowledge(successor)?.is_none() {
                return Err(LodestarError::NotFound(successor.to_string()));
            }
        }
        let changed = self.conn.execute(
            "UPDATE knowledge
             SET retired_at = ?2, retired_by = ?3, retired_reason = ?4, superseded_by = ?5
             WHERE id = ?1 AND retired_at IS NULL",
            params![id, now, human, reason, superseded_by],
        )?;
        if changed == 0 {
            return Err(LodestarError::Invalid(format!(
                "knowledge already retired: {id}"
            )));
        }
        self.get_knowledge(id)?
            .ok_or_else(|| LodestarError::NotFound(id.to_string()))
    }

    /// Purge knowledge that decayed below the threshold without reconfirmation.
    pub fn prune_knowledge(&self, now: i64) -> Result<usize> {
        let removed = self.conn.execute(
            "DELETE FROM knowledge WHERE effective_weight(weight, half_life_hours, confirmed_at, ?1) < ?2",
            params![now, ACTIVE_THRESHOLD],
        )?;
        Ok(removed)
    }
}

fn upsert_knowledge(
    connection: &Connection,
    statement: &str,
    evidence: &str,
    half_life_hours: f64,
    now: i64,
) -> Result<String> {
    let id = format!("knowledge:{}", short_hash(statement));
    connection.execute(
        "INSERT INTO knowledge (id, statement, evidence, weight, half_life_hours, confirmed_at, created_at)
         VALUES (?1, ?2, ?3, 1.0, ?4, ?5, ?5)
         ON CONFLICT(id) DO UPDATE SET
             weight = MIN(1.0, knowledge.weight + 0.1),
             evidence = excluded.evidence,
             half_life_hours = excluded.half_life_hours,
             confirmed_at = excluded.confirmed_at",
        params![id, statement, evidence, half_life_hours, now],
    )?;
    Ok(id)
}

fn row_to_knowledge(row: &Row) -> rusqlite::Result<Knowledge> {
    Ok(Knowledge {
        id: row.get(0)?,
        statement: row.get(1)?,
        evidence: row.get(2)?,
        weight: row.get(3)?,
        half_life_hours: row.get(4)?,
        confirmed_at: row.get(5)?,
        created_at: row.get(6)?,
        retired_at: row.get(7)?,
        retired_by: row.get(8)?,
        retired_reason: row.get(9)?,
        superseded_by: row.get(10)?,
    })
}

#[cfg(test)]
mod tests {
    use super::LodestarStore;
    use crate::embed::{self, Embedder};
    use crate::store::test_support::{store, HOUR, NOW};

    /// Point the optional embedder at the discard port so these tests exercise
    /// the unreachable path deterministically, whether or not the machine
    /// running them happens to have a local model listening.
    fn without_an_embedder() {
        std::env::set_var("LODESTAR_EMBED_URL", "http://127.0.0.1:9");
    }

    // Regression: the semantic index is an optimisation on *reading* knowledge,
    // so an absent or unreachable embedder must cost the reader ranking and
    // nothing else. If the embed attempt could propagate, an agent recording a
    // hard-won lesson would lose it outright because an optional local model
    // was not running - the write path silently acquiring a network dependency.
    #[test]
    fn an_unreachable_embedder_never_costs_us_the_lesson() {
        without_an_embedder();
        let s = store();

        let k = s
            .record_knowledge("never use --no-verify", "{}", 720.0, NOW)
            .unwrap();

        assert_eq!(
            s.get_knowledge(&k.id).unwrap().unwrap().statement,
            k.statement
        );
        assert_eq!(s.active_knowledge(NOW).unwrap().len(), 1);
    }

    #[test]
    fn ranking_orders_by_meaning_not_by_the_order_it_was_given() {
        let s = store();
        let worktrees = s
            .record_knowledge("one worktree per workstream", "{}", 720.0, NOW)
            .unwrap();
        let hooks = s
            .record_knowledge("never use --no-verify", "{}", 720.0, NOW)
            .unwrap();
        // A stub embedder: two statements placed on opposite axes, so the
        // expected ranking is unambiguous.
        embed::store_vector(&s.conn, &worktrees.id, "stub", &[1.0, 0.0], NOW).unwrap();
        embed::store_vector(&s.conn, &hooks.id, "stub", &[0.0, 1.0], NOW).unwrap();

        let near_hooks = s
            .rank_knowledge(s.active_knowledge(NOW).unwrap(), &[0.1, 1.0], "stub")
            .unwrap()
            .0;
        let near_worktrees = s
            .rank_knowledge(s.active_knowledge(NOW).unwrap(), &[1.0, 0.1], "stub")
            .unwrap()
            .0;

        // Both directions, because an implementation that simply preserved the
        // incoming order would pass either one alone.
        assert_eq!(near_hooks[0].id, hooks.id);
        assert_eq!(near_worktrees[0].id, worktrees.id);
    }

    // Regression: rank_knowledge returned Some as soon as ANY vector existed,
    // so a partly-warmed index pinned every unembedded lesson to score 0.0 at
    // the bottom while the reply still called itself "semantic". That is the
    // silent-wrong-answer shape ADR-0080 exists to prevent, arriving through
    // the fix for it: the reader cannot tell a genuinely poor match from one
    // that was never compared at all.
    #[test]
    fn a_partly_indexed_corpus_reports_how_much_it_actually_ranked() {
        let s = store();
        let indexed = s
            .record_knowledge("one worktree per workstream", "{}", 720.0, NOW)
            .unwrap();
        let unindexed = s
            .record_knowledge("never use --no-verify", "{}", 720.0, NOW)
            .unwrap();
        embed::store_vector(&s.conn, &indexed.id, "stub", &[1.0, 0.0], NOW).unwrap();

        let (ordered, covered) = s
            .rank_knowledge(s.active_knowledge(NOW).unwrap(), &[1.0, 0.0], "stub")
            .unwrap();

        assert_eq!(covered, 1, "only one lesson could be compared");
        assert_eq!(ordered.len(), 2, "the unranked lesson is kept, not dropped");
        assert_eq!(ordered[0].id, indexed.id);
        assert_eq!(ordered[1].id, unindexed.id);
    }

    #[test]
    fn missing_vectors_names_only_what_has_not_been_embedded() {
        let s = store();
        let indexed = s.record_knowledge("a", "{}", 720.0, NOW).unwrap();
        let unindexed = s.record_knowledge("b", "{}", 720.0, NOW).unwrap();
        embed::store_vector(&s.conn, &indexed.id, "stub", &[1.0], NOW).unwrap();

        let ids = vec![indexed.id.clone(), unindexed.id.clone()];
        let missing = embed::missing_vectors(&s.conn, "stub", &ids).unwrap();

        assert_eq!(missing, vec![unindexed.id]);
    }

    #[test]
    fn backfill_against_an_unreachable_model_changes_nothing() {
        without_an_embedder();
        let s = store();
        s.record_knowledge("never use --no-verify", "{}", 720.0, NOW)
            .unwrap();
        let active = s.active_knowledge(NOW).unwrap();

        let stored = s.backfill_embeddings(&active, &Embedder::default(), NOW);

        assert_eq!(stored, 0);
        // Still readable, still complete - the warm-up is an optimisation and
        // failing it must not cost the reader the lessons themselves.
        assert_eq!(s.active_knowledge(NOW).unwrap().len(), 1);
        let ids: Vec<String> = active.iter().map(|k| k.id.clone()).collect();
        assert_eq!(
            embed::missing_vectors(&s.conn, &Embedder::default().model, &ids)
                .unwrap()
                .len(),
            1
        );
    }

    #[test]
    fn backfill_is_a_no_op_once_everything_is_indexed() {
        without_an_embedder();
        let s = store();
        let k = s.record_knowledge("a", "{}", 720.0, NOW).unwrap();
        let embedder = Embedder::default();
        embed::store_vector(&s.conn, &k.id, &embedder.model, &[1.0], NOW).unwrap();

        // Nothing is missing, so it must not reach for the network at all -
        // otherwise every search pays a failed round trip forever.
        assert_eq!(
            s.backfill_embeddings(&s.active_knowledge(NOW).unwrap(), &embedder, NOW),
            0
        );
    }

    #[test]
    fn ranking_declines_rather_than_calling_arbitrary_order_semantic() {
        let s = store();
        s.record_knowledge("never use --no-verify", "{}", 720.0, NOW)
            .unwrap();

        // Nothing is indexed under this model, so every statement would score
        // zero and the resulting order would mean nothing. Reporting zero
        // coverage is what lets the caller degrade honestly instead of
        // dressing up noise.
        let (ordered, covered) = s
            .rank_knowledge(s.active_knowledge(NOW).unwrap(), &[1.0, 0.0], "stub")
            .unwrap();

        assert_eq!(covered, 0);
        assert_eq!(ordered.len(), 1);
    }

    #[test]
    fn the_fallback_matches_literal_text_in_statement_or_evidence() {
        let s = store();
        s.record_knowledge("never use --no-verify", "{}", 720.0, NOW)
            .unwrap();
        s.record_knowledge(
            "one worktree per workstream",
            "{\"why\":\"hooks\"}",
            720.0,
            NOW,
        )
        .unwrap();

        let active = s.active_knowledge(NOW).unwrap();
        // Case-insensitive, and evidence counts: a lesson's provenance is often
        // where the term the reader remembers actually appears.
        assert_eq!(
            LodestarStore::substring_knowledge(active.clone(), "NO-VERIFY").len(),
            1
        );
        assert_eq!(
            LodestarStore::substring_knowledge(active.clone(), "hooks").len(),
            1
        );
        assert!(LodestarStore::substring_knowledge(active, "kubernetes").is_empty());
    }

    #[test]
    fn knowledge_revalidation_extends_life() {
        let s = store();
        let k = s.record_knowledge("X breaks Y", "{}", 720.0, NOW).unwrap();
        // Far in the future, unconfirmed knowledge has faded out.
        let far = NOW + 200 * 24 * HOUR;
        assert!(s.active_knowledge(far).unwrap().is_empty());
        // Reconfirming resets the clock so it is active again at that time.
        assert!(s.reconfirm_knowledge(&k.id, far).unwrap());
        assert_eq!(s.active_knowledge(far).unwrap().len(), 1);
    }

    // Regression: re-recording an existing statement silently kept the original
    // half-life (the ON CONFLICT clause updated weight/evidence/confirmed_at but
    // not half_life_hours), so a caller's revised revalidation cadence was lost.
    #[test]
    fn record_knowledge_updates_half_life_on_conflict() {
        let s = store();
        let first = s.record_knowledge("X breaks Y", "{}", 720.0, NOW).unwrap();
        assert_eq!(first.half_life_hours, 720.0);
        let second = s.record_knowledge("X breaks Y", "{}", 24.0, NOW).unwrap();
        assert_eq!(second.id, first.id);
        assert_eq!(second.half_life_hours, 24.0);
    }

    #[test]
    fn one_memory_source_reconfirms_without_duplicate_knowledge() {
        let s = store();
        let source = "/memories/repo/build.md#hooks";
        let first = s
            .record_sourced_knowledge(
                "Never skip hooks",
                r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
                720.0,
                source,
                "agent-a",
                NOW,
            )
            .unwrap();
        let second = s
            .record_sourced_knowledge(
                "Never skip hooks",
                r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
                720.0,
                source,
                "agent-a",
                NOW + HOUR,
            )
            .unwrap();

        assert_eq!(first.0.id, second.0.id);
        assert_eq!(second.1, None);
        assert_eq!(s.active_knowledge(NOW + HOUR).unwrap().len(), 1);
        assert_eq!(
            s.active_knowledge_for_source(source).unwrap().unwrap().id,
            first.0.id
        );
    }

    // Regression: editable memory used to have no stable identity in Lodestar.
    // Recording revised text created a second active lesson, so the old and new
    // instructions could both reach the next agent. The source mapping makes an
    // edit an attributed supersession instead of an accumulating contradiction.
    #[test]
    fn editing_one_memory_source_retires_its_previous_lesson() {
        let s = store();
        let source = "/memories/repo/build.md#hooks";
        let old = s
            .record_sourced_knowledge(
                "Hooks are optional",
                r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
                720.0,
                source,
                "agent-a",
                NOW,
            )
            .unwrap()
            .0;
        let (new, replaced) = s
            .record_sourced_knowledge(
                "Hooks are mandatory",
                r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
                720.0,
                source,
                "agent-b",
                NOW + HOUR,
            )
            .unwrap();

        assert_eq!(replaced.as_deref(), Some(old.id.as_str()));
        assert_eq!(
            s.active_knowledge_for_source(source).unwrap().unwrap().id,
            new.id
        );
        assert_eq!(s.active_knowledge(NOW + HOUR).unwrap().len(), 1);
        let retired = s.get_knowledge(&old.id).unwrap().unwrap();
        assert_eq!(retired.superseded_by.as_deref(), Some(new.id.as_str()));
        assert_eq!(retired.retired_by.as_deref(), Some("agent-b"));
        assert!(retired.retired_reason.unwrap().contains(source));
    }

    #[test]
    fn editing_one_of_two_sources_keeps_the_still_backed_lesson_active() {
        let s = store();
        let old = s
            .record_sourced_knowledge(
                "Hooks are mandatory",
                r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
                720.0,
                "/memories/repo/build.md#hooks",
                "agent-a",
                NOW,
            )
            .unwrap()
            .0;
        s.record_sourced_knowledge(
            "Hooks are mandatory",
            r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
            720.0,
            "/memories/repo/release.md#hooks",
            "agent-a",
            NOW,
        )
        .unwrap();

        let (new, superseded) = s
            .record_sourced_knowledge(
                "Hooks also run on documentation changes",
                r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
                720.0,
                "/memories/repo/build.md#hooks",
                "agent-b",
                NOW + HOUR,
            )
            .unwrap();

        assert_eq!(
            superseded, None,
            "the other source still backs the old lesson"
        );
        assert_eq!(s.active_knowledge(NOW + HOUR).unwrap().len(), 2);
        assert_eq!(
            s.active_knowledge_for_source("/memories/repo/release.md#hooks")
                .unwrap()
                .unwrap()
                .id,
            old.id
        );
        assert_eq!(
            s.active_knowledge_for_source("/memories/repo/build.md#hooks")
                .unwrap()
                .unwrap()
                .id,
            new.id
        );
        assert!(!s.get_knowledge(&old.id).unwrap().unwrap().retired());
    }

    #[test]
    fn detaching_sources_retires_a_lesson_only_after_the_last_one() {
        let s = store();
        let first = "/memories/repo/build.md#hooks";
        let second = "/memories/repo/release.md#hooks";
        let knowledge = s
            .record_sourced_knowledge(
                "Hooks are mandatory",
                r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
                720.0,
                first,
                "agent-a",
                NOW,
            )
            .unwrap()
            .0;
        s.record_sourced_knowledge(
            "Hooks are mandatory",
            r#"{"nodes":["artifact:.pre-commit-config.yaml"]}"#,
            720.0,
            second,
            "agent-a",
            NOW,
        )
        .unwrap();

        let (still_active, retired) = s
            .retire_knowledge_source(first, "agent-a", "memory deleted", NOW + HOUR)
            .unwrap();
        assert!(!retired);
        assert!(!still_active.retired());
        assert!(s.active_knowledge_for_source(first).unwrap().is_none());
        assert_eq!(
            s.active_knowledge_for_source(second).unwrap().unwrap().id,
            knowledge.id
        );

        let (retired_knowledge, retired) = s
            .retire_knowledge_source(second, "agent-b", "memory deleted", NOW + 2 * HOUR)
            .unwrap();
        assert!(retired);
        assert!(retired_knowledge.retired());
        assert_eq!(retired_knowledge.retired_by.as_deref(), Some("agent-b"));
        assert!(s.active_knowledge(NOW + 2 * HOUR).unwrap().is_empty());
    }

    // ADR-0022: knowledge is durable-but-revalidated, not immortal. Unreconfirmed
    // knowledge decays below the active threshold and prune_knowledge removes it,
    // while a reconfirmed statement survives the same prune.
    #[test]
    fn unreconfirmed_knowledge_decays_and_is_pruned_but_reconfirmed_survives() {
        let s = store();
        let stale = s
            .record_knowledge("stale lesson", "{}", 720.0, NOW)
            .unwrap();
        let fresh = s
            .record_knowledge("fresh lesson", "{}", 720.0, NOW)
            .unwrap();
        let far = NOW + 200 * 24 * HOUR;

        // The fresh one is reconfirmed at the far time; the stale one is not.
        assert!(s.reconfirm_knowledge(&fresh.id, far).unwrap());

        // Only the un-reconfirmed statement has faded from the active set...
        let active = s.active_knowledge(far).unwrap();
        assert_eq!(active.len(), 1);
        assert_eq!(active[0].id, fresh.id);

        // ...and prune removes exactly that decayed one, keeping the reconfirmed.
        assert_eq!(s.prune_knowledge(far).unwrap(), 1);
        assert!(s.get_knowledge(&stale.id).unwrap().is_none());
        assert!(s.get_knowledge(&fresh.id).unwrap().is_some());
    }

    #[test]
    fn pruning_sourced_knowledge_removes_its_source_mapping() {
        let s = store();
        let source = "/memories/session/notes.md#stale";
        s.record_sourced_knowledge(
            "stale sourced lesson",
            r#"{"nodes":["artifact:src/a.rs"]}"#,
            1.0,
            source,
            "agent-a",
            NOW,
        )
        .unwrap();

        assert_eq!(s.prune_knowledge(NOW + 24 * HOUR).unwrap(), 1);
        assert!(s.active_knowledge_for_source(source).unwrap().is_none());
    }

    // A lesson that is wrong or replaced leaves the active set at once, instead
    // of competing for advisory slots until its half-life runs out. It is not
    // deleted: the statement and its provenance stay readable, alongside who
    // ended it and why.
    #[test]
    fn a_retired_lesson_leaves_the_active_set_but_keeps_its_record() {
        let s = store();
        let wrong = s
            .record_knowledge("wrong lesson", "{}", 720.0, NOW)
            .unwrap();
        let kept = s.record_knowledge("kept lesson", "{}", 720.0, NOW).unwrap();
        assert_eq!(s.active_knowledge(NOW).unwrap().len(), 2);

        let retired = s
            .retire_knowledge(&wrong.id, "Reviewer", "measured false", None, NOW)
            .unwrap();

        assert_eq!(retired.retired_at, Some(NOW));
        assert_eq!(retired.retired_by.as_deref(), Some("Reviewer"));
        assert_eq!(retired.retired_reason.as_deref(), Some("measured false"));
        assert!(retired.retired());

        let active = s.active_knowledge(NOW).unwrap();
        assert_eq!(active.len(), 1);
        assert_eq!(active[0].id, kept.id);

        // Retiring is not deleting (ADR-0019): the row is still readable.
        let stored = s.get_knowledge(&wrong.id).unwrap().unwrap();
        assert_eq!(stored.statement, "wrong lesson");
    }

    // Guarded in one statement, so the original actor and reason survive a
    // second attempt rather than being quietly overwritten by it.
    #[test]
    fn retiring_refuses_an_unknown_id_and_a_second_retirement() {
        let s = store();
        let k = s.record_knowledge("a lesson", "{}", 720.0, NOW).unwrap();

        let missing = s
            .retire_knowledge("knowledge:nope", "Reviewer", "why", None, NOW)
            .unwrap_err();
        assert!(missing.to_string().contains("knowledge:nope"), "{missing}");

        s.retire_knowledge(&k.id, "First", "the real reason", None, NOW)
            .unwrap();
        let again = s
            .retire_knowledge(&k.id, "Second", "a later reason", None, NOW + HOUR)
            .unwrap_err();
        assert!(again.to_string().contains("already retired"), "{again}");

        let stored = s.get_knowledge(&k.id).unwrap().unwrap();
        assert_eq!(stored.retired_by.as_deref(), Some("First"));
        assert_eq!(stored.retired_reason.as_deref(), Some("the real reason"));
        assert_eq!(stored.retired_at, Some(NOW));
    }

    // A replacement must exist, or the reader is left with a withdrawn lesson
    // and nowhere to go.
    #[test]
    fn superseding_records_the_successor_and_refuses_a_dangling_or_self_link() {
        let s = store();
        let old = s.record_knowledge("old lesson", "{}", 720.0, NOW).unwrap();
        let new = s.record_knowledge("new lesson", "{}", 720.0, NOW).unwrap();

        let dangling = s
            .retire_knowledge(&old.id, "R", "replaced", Some("knowledge:ghost"), NOW)
            .unwrap_err();
        assert!(
            dangling.to_string().contains("knowledge:ghost"),
            "{dangling}"
        );

        let itself = s
            .retire_knowledge(&old.id, "R", "replaced", Some(&old.id), NOW)
            .unwrap_err();
        assert!(itself.to_string().contains("supersede itself"), "{itself}");

        let retired = s
            .retire_knowledge(&old.id, "R", "replaced", Some(&new.id), NOW)
            .unwrap();
        assert_eq!(retired.superseded_by.as_deref(), Some(new.id.as_str()));
    }
}
